"""Tests for provenance generated by schema-v2 adapter builds."""

import hashlib
import json
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

from engine.adapters.config import (
    AdapterConfig,
    BuildConfig,
    FuzzerConfig,
    ResourceLimits,
    TargetConfig,
)
from engine.fuzzing.provenance import verify_build_provenance


class AdapterBuildProvenanceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.base = Path(self.temp.name)

        self.root = self.base / "repository"
        self.target_dir = self.root / "targets" / "libpng"
        self.build_dir = self.base / "build"
        self.source_dir = self.base / "source"
        self.seed_dir = self.base / "seeds"
        self.output_dir = self.base / "output"

        for directory in (
            self.target_dir, self.build_dir, self.source_dir,
            self.seed_dir, self.output_dir,
        ):
            directory.mkdir(parents=True)

        self.config_path = self.target_dir / "adapter.toml"
        self.config_path.write_text("# test adapter\n")

        self.harness_source = self.target_dir / "png_read_harness.c"
        self.harness_source.write_text("/* harness fixture */\n")

        self.binary = self.build_dir / "kekkai_png_harness"
        self.binary.write_bytes(b"fake executable")
        self.binary.chmod(0o755)

        self.archive = self.build_dir / "libpng16.a"
        self.archive.write_bytes(b"fake archive")

        self.cache = self.build_dir / "CMakeCache.txt"
        cache_values = {
            "CMAKE_BUILD_TYPE": "RelWithDebInfo",
            "CMAKE_C_COMPILER": "/usr/bin/afl-clang-fast",
            "CMAKE_GENERATOR": "Ninja",
            "CMAKE_MAKE_PROGRAM": "/usr/bin/ninja",
            "CMAKE_EXPORT_COMPILE_COMMANDS": "ON",
            "CMAKE_POSITION_INDEPENDENT_CODE": "ON",
            "AWK": "/usr/bin/gawk",
            "PNG_BUILD_ZLIB": "OFF",
            "PNG_EXECUTABLES": "ON",
            "PNG_FRAMEWORK": "OFF",
            "PNG_HARDWARE_OPTIMIZATIONS": "ON",
            "PNG_INTEL_SSE": "on",
            "PNG_STATIC": "ON",
            "PNG_SHARED": "OFF",
            "PNG_TESTS": "OFF",
            "PNG_TOOLS": "OFF",
            "ZLIB_INCLUDE_DIR": "/usr/include",
            "ZLIB_LIBRARY_RELEASE": "/usr/lib/x86_64-linux-gnu/libz.so",
        }
        self.cache.write_text(
            "".join(
                f"{key}:STRING={value}\n"
                for key, value in cache_values.items()
            )
        )

        self.database = self.build_dir / "compile_commands.json"
        compiler = "/usr/bin/afl-clang-fast"
        entries = [
            {
                "directory": str(self.build_dir),
                "file": f"source-{index}.c",
                "arguments": [compiler, "-c", f"source-{index}.c"],
            }
            for index in range(17)
        ]
        self.database.write_text(json.dumps(entries))

        self.header = self.build_dir / "pnglibconf.h"
        self.header.write_text("".join(
            f"#define {feature}\n"
            for feature in (
                "PNG_READ_SUPPORTED",
                "PNG_SEQUENTIAL_READ_SUPPORTED",
                "PNG_READ_ANCILLARY_CHUNKS_SUPPORTED",
                "PNG_READ_INTERLACING_SUPPORTED",
                "PNG_SETJMP_SUPPORTED",
                "PNG_SET_USER_LIMITS_SUPPORTED",
            )
        ))

        self.config = AdapterConfig(
            schema_version=2,
            target=TargetConfig(
                name="libpng",
                version="1.6.59",
                source_dir=self.source_dir,
                harness_source=self.harness_source,
                harness_binary=self.binary,
                seed_dir=self.seed_dir,
                output_parent=self.output_dir,
            ),
            fuzzer=FuzzerConfig("afl-fuzz", "4.33c"),
            limits=ResourceLimits(300, 512, 1000, 8388608),
            config_path=self.config_path,
            build=BuildConfig(
                profile="libpng-afl-ubsan",
                build_dir=self.build_dir,
                jobs=2,
                timeout_seconds=900,
                memory_mib=4096,
                log_limit_bytes=16777216,
            ),
        )

        def digest(path):
            return hashlib.sha256(path.read_bytes()).hexdigest()

        self.metadata = {
            "schema_version": 1,
            "status": "completed",
            "target": "libpng",
            "target_version": "1.6.59",
            "profile": "libpng-afl-ubsan",
            "build_dir": str(self.build_dir),
            "adapter_config": str(self.config_path),
            "steps": [
                {
                    "name": name,
                    "status": "completed",
                    "exit_code": 0,
                }
                for name in ("configure", "library", "harness")
            ],
            "environment": {
                "AFL_USE_UBSAN": "1",
                "AFL_DEBUG": "1",
            },
            "artifacts": {
                "harness_source_sha256": digest(self.harness_source),
                "harness_binary_sha256": digest(self.binary),
                "library_archive_sha256": digest(self.archive),
                "cmake_cache_sha256": digest(self.cache),
                "compile_database_sha256": digest(self.database),
                "generated_header_sha256": digest(self.header),
            },
        }
        (self.build_dir / "build.json").write_text(
            json.dumps(self.metadata)
        )

    def tearDown(self):
        self.temp.cleanup()

    def verify(self):
        from engine.fuzzing import provenance

        original_read = provenance._read_bounded_file

        def bounded_read(path, maximum):
            if path == Path("/usr/include/zlib.h"):
                return b'#define ZLIB_VERSION "1.3.1"\n'
            return original_read(path, maximum)

        def version(command):
            if "afl-fuzz" in command[0]:
                return 0, "afl-fuzz++4.33c\n"
            return 0, "Ubuntu clang version 21.1.8 (6ubuntu1)\n"

        with (
            patch("engine.fuzzing.provenance.shutil.which",
                  return_value="/usr/bin/afl-fuzz"),
            patch("engine.fuzzing.provenance._run_bounded_version",
                  side_effect=version),
            patch("engine.fuzzing.provenance._read_bounded_file",
                  side_effect=bounded_read),
        ):
            return verify_build_provenance(self.config, self.root)

    def test_accepts_completed_adapter_build(self):
        report = self.verify()
        self.assertTrue(report.passed, report.format())

    def test_rejects_modified_build_binary(self):
        self.binary.write_bytes(b"modified executable")
        report = self.verify()

        self.assertFalse(report.passed)
        check = next(
            item for item in report.checks
            if item.name == "harness_binary_sha256"
        )
        self.assertEqual(check.status, "failed")

    def test_rejects_incomplete_build_state(self):
        self.metadata["status"] = "failed"
        (self.build_dir / "build.json").write_text(
            json.dumps(self.metadata)
        )

        report = self.verify()
        self.assertFalse(report.passed)

    def test_rejects_missing_build_step(self):
        self.metadata["steps"][1]["status"] = "failed"
        (self.build_dir / "build.json").write_text(
            json.dumps(self.metadata)
        )

        report = self.verify()
        self.assertFalse(report.passed)


if __name__ == "__main__":
    unittest.main()
